    /** The trade-off between search quality and response time. Update search always uses keyword matching regardless of strategy.
     * @default BALANCED
     */
    strategy?: 'BALANCED' | 'QUALITY' | 'SPEED' | Expression<string>;
    /** Only return results updated after this time
     */
    updatedAfter?: string | Expression<string>;
    /** Only return results updated before this time
     */
